const e = $('Error Trigger').first().json;
const wfName = e.workflow?.name || 'unknown workflow';
const nodeName = e.execution?.lastNodeExecuted || 'unknown node';
const msg = (e.execution?.error?.message || 'no message').slice(0, 800);
const url = e.execution?.url || '';
let hint = 'Check the execution in n8n for details.';
if (/401|unauthor|invalid token|expired/i.test(msg)) hint = '401: an account needs to be reconnected. Open n8n > Credentials and re-authenticate.';
else if (/429|rate limit|too many/i.test(msg)) hint = '429: rate limit. Open the failed node, turn on Retry On Fail, save.';
else if (/timeout|ETIMEDOUT|ECONNRESET/i.test(msg)) hint = 'Timeout: open the execution and click Retry.';
const subject = `n8n error: ${wfName}`;
const text = `${wfName} failed at ${nodeName}\n\n${msg}\n\nWhat to do: ${hint}\n${url}`;
return [{ json: { subject, text, to: 'you@example.com' } }];
